import json
from pathlib import Path
from collections import Counter
from datetime import datetime,timezone
home=Path("/home/admin1")
cut=datetime.fromisoformat("2026-10-16T01:25:11+00:00")
stop=datetime.fromisoformat("2026-10-16T05:15:00+00:00")
print("CODEX_LOG_PATH_EXISTS="+str((home/".codex").exists()))
roots=[home/".codex"/"sessions",home/".codex"/"archived_sessions"]
sessions=[]
for root in roots:
 if not root.is_dir():
  print("CODEX_ROOT_"+root.name+"=ABSENT")
  continue
 try:
  paths=list(root.glob("2026/10/16/*.jsonl"))+list(root.glob("2026/10/15/*.jsonl"))
 except OSError:
  paths=[]
 print("CODEX_ROOT_"+root.name+"_FILECOUNT="+str(len(paths)))
 sessions.extend(paths[:300])
for p in sessions[:120]:
 first=last=None
 counts=Counter()
 last_total=None
 try:
  with p.open(encoding="utf-8",errors="replace") as fh:
   for index,line in enumerate(fh):
    if index>=50000:break
    try: e=json.loads(line)
    except ValueError:continue
    try: at=datetime.fromisoformat(str(e.get("timestamp","")).replace("Z","+00:00")).astimezone(timezone.utc)
    except ValueError:continue
    if not cut<=at<=stop:continue
    first=first or at
    last=at
    obj=e.get("payload")
    obj=obj if isinstance(obj,dict) else {}
    typ=obj.get("type")
    if typ=="token_count":
     counts["token_count_after_review"]+=1
     usage=(obj.get("info") or {}).get("total_token_usage") or {}
     if isinstance(usage,dict):last_total=usage.get("total_tokens")
    elif typ in ("message","function_call","custom_tool_call"):
     counts[typ+"_after_review"]+=1
 except OSError:continue
 if first:
  print("CODEX_ACTIVITY="+json.dumps({"first":first.isoformat(),"last":last.isoformat(),"counts":dict(counts),"last_session_total_tokens":last_total},separators=(",",":")))
print("CODEX_SESSION_FILES_CHECKED="+str(len(sessions)))
